<script setup lang="ts">
import { computed, watch } from 'vue'
import { ArrowLeft, Minus, Plus, ShoppingBag, Trash2 } from '@lucide/vue'
import { RouterLink } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { useB2BCartStore } from '../stores/b2bCart'

const auth = useAuthStore(); const cart = useB2BCartStore()
const scope = computed(() => `${auth.bootstrap?.user.id || 'guest'}_${auth.bootstrap?.company.id || 'company'}_${auth.selectedPortalAccount || 'default'}`)
watch(scope, value => { void cart.load(value) }, { immediate: true })
const money = (minor: number) => new Intl.NumberFormat(auth.locale === 'ar' ? 'ar-EG' : 'en-EG', { style: 'currency', currency: 'EGP' }).format(minor / 100)
const deliveryNote = 'Shipping and payment options will be added when the B2B order service is connected.'
async function changeQuantity(sku: string, quantity: number) { try { await cart.setQuantity(sku, quantity) } catch { /* retain the server validation message */ } }
async function removeItem(sku: string) { try { await cart.remove(sku) } catch { /* retain the request error */ } }
async function clearBasket() { try { await cart.clear() } catch { /* retain the request error */ } }
</script>
<template>
  <div class="b2b-cart-page">
    <header class="page-heading"><div><span class="eyebrow">B2B CATALOG</span><h1>Your basket</h1><p>{{ cart.itemCount }} units across {{ cart.items.length }} products</p></div><RouterLink to="/products" class="button secondary"><ArrowLeft :size="16"/> Continue shopping</RouterLink></header>
    <div v-if="cart.error" class="form-error b2b-cart-error">{{ cart.error }}</div><div v-if="cart.loading" class="table-empty"><ShoppingBag/><strong>Loading basket</strong><span>Loading your account-specific basket.</span></div><div v-else-if="!cart.items.length" class="data-panel b2b-cart-empty"><ShoppingBag/><h2>Your basket is empty</h2><p>Browse the catalog and add products to start a sample order.</p><RouterLink to="/products" class="button primary">Browse products</RouterLink></div>
    <div v-else-if="!cart.loading" class="b2b-cart-layout">
      <section class="data-panel b2b-cart-lines"><header><div><span class="eyebrow">SAMPLE ORDER</span><h2>Basket items</h2></div><button class="button subtle b2b-clear-button" @click="clearBasket"><Trash2 :size="15"/> Clear basket</button></header>
        <article v-for="item in cart.items" :key="item.sku" class="b2b-cart-line"><img :src="item.image" :alt="item.name"><div class="b2b-cart-product"><small>{{ item.sku }} · {{ item.category }}</small><strong>{{ item.name }}</strong><span>{{ item.stock_status }}</span></div><div class="b2b-cart-quantity"><button :aria-label="`Remove one case of ${item.name}`" :disabled="item.quantity <= item.case_quantity" @click="changeQuantity(item.sku, item.quantity - item.case_quantity)"><Minus :size="14"/></button><span>{{ item.quantity }}</span><button :aria-label="`Add one case of ${item.name}`" @click="changeQuantity(item.sku, item.quantity + item.case_quantity)"><Plus :size="14"/></button><small>Case of {{ item.case_quantity }}</small></div><strong class="b2b-line-total">{{ money(item.price_minor * item.quantity) }}</strong><button class="icon-button b2b-remove-line" :aria-label="`Remove ${item.name}`" @click="removeItem(item.sku)"><Trash2 :size="16"/></button></article>
      </section>
      <aside class="data-panel b2b-order-summary"><span class="eyebrow">ORDER SUMMARY</span><h2>Sample total</h2><div><span>Items subtotal</span><strong>{{ money(cart.subtotalMinor) }}</strong></div><div><span>Delivery</span><span>Calculated at checkout</span></div><hr><div class="b2b-summary-total"><span>Estimated total</span><strong>{{ money(cart.subtotalMinor) }}</strong></div><button class="button primary wide" disabled>Checkout unavailable</button><p>{{ deliveryNote }}</p><small>{{ auth.portalDemoMode ? "Demo basket only. No order or payment is submitted." : "No order or payment is submitted from this basket yet." }}</small></aside>
    </div>
  </div>
</template>
<style scoped>
.b2b-cart-layout{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:17px;align-items:start}.b2b-cart-lines,.b2b-order-summary{border:1px solid var(--line);border-radius:12px;background:#fff}.b2b-cart-lines>header{display:flex;align-items:center;justify-content:space-between;padding:19px 21px;border-bottom:1px solid var(--line)}.b2b-cart-lines h2,.b2b-order-summary h2{margin:4px 0 0;font-size:16px}.b2b-clear-button{display:inline-flex;align-items:center;gap:7px}.b2b-cart-line{display:grid;grid-template-columns:68px minmax(130px,1fr) auto auto 30px;align-items:center;gap:15px;padding:15px 19px;border-bottom:1px solid #eef0ed}.b2b-cart-line:last-child{border-bottom:0}.b2b-cart-line>img{width:68px;height:64px;object-fit:cover;border-radius:8px;background:#f4f6f3}.b2b-cart-product{display:grid;gap:5px}.b2b-cart-product small,.b2b-cart-product span{color:var(--muted);font-size:9px}.b2b-cart-product strong{font-size:11px}.b2b-cart-quantity{display:grid;grid-template-columns:28px 34px 28px;align-items:center;justify-items:center;gap:3px}.b2b-cart-quantity button{width:27px;height:27px;display:grid;place-items:center;border:1px solid var(--line);border-radius:7px;background:#fff;color:var(--ink)}.b2b-cart-quantity button:disabled{opacity:.4}.b2b-cart-quantity>span{font-size:11px;font-weight:700}.b2b-cart-quantity small{grid-column:1/-1;color:var(--muted);font-size:8px}.b2b-line-total{font-size:11px;white-space:nowrap}.b2b-remove-line{color:#a35b50}.b2b-order-summary{position:sticky;top:18px;padding:20px}.b2b-order-summary>div{display:flex;justify-content:space-between;gap:14px;margin-top:17px;color:var(--muted);font-size:10px}.b2b-order-summary>div strong{color:var(--ink)}.b2b-order-summary hr{margin:18px 0;border:0;border-top:1px solid var(--line)}.b2b-order-summary .b2b-summary-total{margin:0 0 17px;color:var(--ink);font-size:12px;font-weight:700}.b2b-order-summary .button{width:100%;margin-top:8px}.b2b-order-summary .button:disabled{opacity:.58;cursor:not-allowed}.b2b-order-summary p,.b2b-order-summary>small{display:block;margin:12px 0 0;color:var(--muted);font-size:9px;line-height:1.6}.b2b-cart-empty{min-height:350px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.b2b-cart-empty>svg{width:36px;height:36px;color:#648376}.b2b-cart-empty h2{margin:15px 0 4px;font-size:17px}.b2b-cart-empty p{margin:0 0 16px;color:var(--muted);font-size:11px}.b2b-cart-empty a{display:inline-flex;align-items:center;justify-content:center}@media(max-width:950px){.b2b-cart-layout{grid-template-columns:1fr}.b2b-order-summary{position:static}}@media(max-width:650px){.b2b-cart-line{grid-template-columns:54px minmax(0,1fr) 32px;gap:10px;padding:13px}.b2b-cart-line>img{width:54px;height:54px}.b2b-cart-quantity{grid-column:2;justify-self:start}.b2b-line-total{grid-column:2;grid-row:2}.b2b-remove-line{grid-column:3;grid-row:1}.b2b-cart-lines>header{padding:15px}.b2b-cart-lines>header .button{padding:8px;font-size:9px}}
</style>
